use std::{fs,path::Path};
use serde_json::{json,Value};
fn main(){let phase=std::env::args().nth(1).expect("phase");let jobs:Vec<String>=std::env::args().skip(2).collect();let entry=json!({"experiment":"stage-costs","root":"/tmp/zopro-stage-costs","phase":phase,"owned_live_jobs":jobs,"production_accepted_unchanged":true,"new_AWS_resources":false,"adopted":false,"goal_achieved":false});for p in ["/tmp/zopro-latest-optimization-status.json","/tmp/zopro-validation-checkpoint/state.json"]{let mut v:Value=serde_json::from_slice(&fs::read(p).unwrap()).unwrap();v["current_work"]=entry.clone();v["owned_live_jobs"]=json!(jobs);v["status"]=json!(phase);fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();}let p=Path::new("/home/ubuntu/src/zopro-cpu-perf-handoff.md");let old=fs::read_to_string(p).unwrap();fs::write(p,format!("# CURRENT — 2026-10-26: STAGE COSTS: {phase}\n\nPrivate root /tmp/zopro-stage-costs; owned live handles {jobs:?}. Accepted170source/SDK unchanged; no cloud/new speed/adoption. Diagnostic nested wall+calling-thread CPU spans,32KiB/512records. Native113core including4recorder tests,raw2/cubic6 pass; field source unchanged. Frozen376SDK22Gnark two-shape accepted/OFF/ON protocol in design.md; pending work must finish/verify/report/commit/PUSH. Previous goal turn status-only/no-progress, this turn implements and measures concrete diagnostic. Goal all-eight CPU10x remains active/unmet.\n\nEarlier headers below are historical and superseded.\n\n{old}")).unwrap();}
